const all = items.map((i) => i.json);
const sul = all.filter((m) => m.microrregiao?.mesorregiao?.nome === 'Sul/Sudoeste de Minas');
if (sul.length === 0) {
  throw new Error('Nenhum município da mesorregião Sul/Sudoeste de Minas encontrado na resposta do IBGE');
}
const mesoId = sul[0].microrregiao.mesorregiao.id;
return [{ json: { mesoId, municipios: sul.map((m) => ({ geocode: m.id, nome: m.nome })) } }];

// A malha do IBGE vem com content-type vnd.geo+json, que o n8n não
// auto-parseia: o corpo chega como string em json.data.
const raw = items[0].json;
const fc = raw.features ? raw : (typeof raw.data === 'string' ? JSON.parse(raw.data) : raw.data);
const { municipios } = $('Filtrar Sul/Sudoeste').first().json;
const byCode = new Map(municipios.map((m) => [String(m.geocode), m.nome]));
return (fc.features || [])
  .filter((f) => byCode.has(String(f.properties.codarea)))
  .map((f) => ({
    json: {
      geocode: Number(f.properties.codarea),
      nome: byCode.get(String(f.properties.codarea)),
      mesorregiao: 'Sul/Sudoeste de Minas',
      geomJson: JSON.stringify(f.geometry),
    },
  }));
